import {useModules} from '../../modules/context.tsx';
import React,{useEffect,useRef} from 'react';
import {EditableEventBar} from './EditableEventBar.jsx';
import {useTimelineDrag} from './useTimelineDrag.js';
import {timelineTracks,trackSelections} from '../../../domain/timeline-tracks.js';
import {usePreference} from '../../shared/state.js';
const kinds={all:'全部',event:'事件',person:'人物',foreshadow:'伏笔'};
const statuses={idea:'讨论中',selected:'考虑采用',written:'已写入正文',dropped:'暂不采用'};
const shadows={planned:'计划',planted:'已埋设',developing:'推进中',recovered:'已回收',abandoned:'已放弃'};
const refs={appearance:'实际出场',mention:'仅被提及',entering:'进入故事',participating:'参与事件'};
export function TimelineTracks({board,novelId,mode,current,choose,onPlan,onEvent,onMemory,onShadow,onPlace,busy}){
 const modules=useModules();
 const [filter,setFilter]=usePreference(`${novelId}:timeline-filter`,'all');
 const safeFilter=!modules.foreshadow&&filter==='foreshadow'?'all':filter,shownBoard=modules.foreshadow?board:{...board,foreshadows:[]};
 const baseTrack=timelineTracks(shownBoard,mode,safeFilter),selections=trackSelections(board,mode),scroll=useRef(null);
 const drag=useTimelineDrag({board,track:baseTrack,mode,scroll,onPlace,busy}),track=drag.drag?.track||baseTrack;
 const selectSlot=s=>choose(selections.find(r=>r.key===s.key)||s);
 const selectMarker=m=>{const slot=track.slots[m.start];if(m.kind==='event')choose({key:m.eventId,eventId:m.eventId,event:m.event,chapterId:slot.chapterId});else {selectSlot(slot);if(m.kind==='person')onMemory(m.id);else onShadow(m.id);}};
 const currentSlot=track.slots.find(s=>s.chapterId&&s.chapterId===current?.chapterId||s.eventId&&s.eventId===current?.eventId);
 useEffect(()=>{const el=scroll.current;if(!el||!currentSlot||drag.drag)return;const top=currentSlot.top;if(top<el.scrollTop+44||top+currentSlot.height>el.scrollTop+el.clientHeight)el.scrollTo({top:Math.max(0,top-44),behavior:'smooth'});},[current?.key,currentSlot?.top,!!drag.drag]);
 const jump=()=>{const m=track.allMarkers.find(m=>m.eventId===current?.eventId),slot=m?track.slots[m.start]:track.slots.find(s=>s.chapterId===current?.chapterId);if(slot)scroll.current?.scrollTo({top:Math.max(0,slot.top-20),behavior:'smooth'});};
 return <section className="timeline-tracks" aria-label="连续时间线"><div className="track-filter" role="group" aria-label="时间线内容筛选">{Object.entries(kinds).filter(([id])=>modules.foreshadow||id!=='foreshadow').map(([id,label])=><button key={id} aria-pressed={filter===id} className={filter===id?'selected':''} disabled={!!drag.drag} onClick={()=>setFilter(id)}>{label}</button>)}<button className="track-locate" onClick={jump}>定位当前</button></div>
 <div className="track-scroll" ref={scroll} tabIndex={0} aria-label="时间线轨道，可上下及左右滚动"><div className="track-world" style={{'--track-lanes':track.lanes,height:track.height}}>
 <div className="track-heading"><span>{mode==='story'?'故事时间':'卷章 / 规划'}</span><span>事件与标记</span></div>
 {track.slots.map((s,i)=><React.Fragment key={s.key}><div className={`track-row-line ${current?.chapterId&&s.chapterId===current.chapterId||current?.key===s.key?'is-current':''}`} style={{top:s.top,height:s.height}}/>
 <article className="track-chapter" style={{top:s.top,height:s.height}}><button className="track-chapter-title" aria-current={current?.key===s.key?'step':undefined} onClick={()=>selectSlot(s)}><small>{s.subtitle}</small><strong>{s.title}</strong></button><div className="track-chapter-actions"><button disabled={busy} aria-label={`添加规划 ${s.title}`} onClick={()=>onPlan(s)}>＋规划</button><button disabled={busy} aria-label={`${s.eventId?'编辑事件':'添加事件'} ${s.title}`} onClick={()=>onEvent(s.eventId||null,s.eventId?undefined:{chapterId:s.chapterId,revision:board.chapters.find(c=>c.id===s.chapterId)?.revision,planned:!s.chapterId})}>{s.eventId?'编辑事件':'＋事件'}</button></div>
 {s.plans.map(p=><button key={p.id} className={`track-plan status-${p.status}`} aria-label={`编辑规划 ${p.title}`} onClick={()=>onPlan(s,p.id)}><strong>{p.title}</strong><small>{statuses[p.status]}</small></button>)}</article></React.Fragment>)}
 {track.markers.map(m=>{const first=track.slots[m.start],last=track.slots[m.end],top=first.top+12,height=last.top+last.height-top-14,selected=m.kind==='event'&&current?.eventId===m.eventId,style={top,height,left:`calc(var(--ruler-width) + ${m.lane} * (var(--lane-width) + 8px) + 6px)`},label=<>
 <span className="track-bar-label"><small>{kinds[m.kind]}{m.planned?' · 计划':''}{m.review?' · 待复核':''}</small><strong>{m.title}</strong><small>{m.kind==='event'?(m.event.storyDate||m.event.storyTime||''):m.kind==='person'?refs[m.referenceKind]:m.linkedOnly?'事件关联':shadows[m.status]}</small>{m.end>m.start&&<small>{first.title} → {last.title}</small>}</span>
 {m.members.filter(i=>i>=m.start&&i<=m.end).map(i=><span className="track-mark" key={i} style={{top:track.slots[i].top+22-top}} title={m.kind==='foreshadow'?m.evidence?.filter(e=>e.chapterId===track.slots[i].chapterId).map(e=>({plant:'埋设',progress:'推进',recover:'回收'}[e.kind])).join(' / ')||(m.target===i?'计划回收':'关联'):track.slots[i].title}/>)}{m.plannedEnd&&<span className="track-end-label">计划回收</span>}</>;
  return m.kind==='event'?<EditableEventBar key={m.key} marker={m} {...{track,board,mode,style,selected,drag,onPlace,busy}} select={selectMarker} onEdit={id=>onEvent(id)}>{label}</EditableEventBar>:<button key={m.key} data-track-id={m.key} data-range-start={m.start} data-range-end={m.end} className={`track-bar kind-${m.kind} ${m.status==='abandoned'?'is-abandoned':''}`} style={style} aria-label={`${kinds[m.kind]} ${m.title}${m.end>m.start?`，跨 ${m.end-m.start+1} 章`:''}`} onClick={()=>selectMarker(m)}>{label}</button>;
 })}
 {!track.slots.length&&<p className="track-empty">添加章节或事件，开始安排故事。</p>}
 </div></div><p className="track-help">{mode==='narration'?'长条连接跨章事件；圆点标出已关联的章节。':'按故事先后排列；人物参与不等于正文出场。'} 点击事件查看阶段关系；点事件上的“设置”、双击或长按可编辑和删除。{mode==='narration'?'拖动 ⠿ 移动，首尾短线调整跨度。':'拖动 ⠿ 调整故事先后，日期保持。'}左右滑动查看其他轨道。</p>
 {track.waiting.length>0&&<details className="story-waiting"><summary>待安排伏笔 · {track.waiting.length}</summary>{track.waiting.map(f=><button key={f.id} className="story-foreshadow" onClick={()=>onShadow(f.id)}><strong>{f.title}</strong><small>{shadows[f.status]} · 未指定时间位置</small></button>)}</details>}
 </section>;
}
export const trackStyles=`
.cuigengji .story-workspace{grid-template-columns:minmax(0,1.25fr) minmax(290px,1fr);gap:22px}.cuigengji .timeline-tracks{min-width:0;--ruler-width:176px;--lane-width:148px}.cuigengji .track-filter{display:flex;gap:4px;flex-wrap:wrap;margin:0 0 12px}.cuigengji .track-filter button{font-size:12px;padding:6px 10px;min-height:34px;border:0;background:transparent;color:var(--cg-muted)}.cuigengji .track-filter button.selected{color:var(--cg-accent);background:color-mix(in srgb,var(--cg-accent) 10%,transparent)}.cuigengji .track-filter .track-locate{margin-left:auto;font-size:11px}.cuigengji .track-scroll{max-height:70dvh;min-height:160px;overflow:auto;overscroll-behavior:contain;touch-action:pan-x pan-y;border:1px solid var(--cg-line);border-radius:10px;background:var(--cg-paper)}.cuigengji .track-world{position:relative;width:calc(var(--ruler-width) + var(--track-lanes) * (var(--lane-width) + 8px) + 12px);min-width:100%}.cuigengji .track-heading{position:sticky;top:0;left:0;display:flex;z-index:5;height:44px;background:var(--cg-paper);border-bottom:1px solid var(--cg-line);font-size:11px;color:var(--cg-muted);align-items:center}.cuigengji .track-heading span:first-child{width:var(--ruler-width);flex:none;padding:0 12px}.cuigengji .track-heading span:last-child{padding-left:12px}.cuigengji .track-row-line{position:absolute;left:0;right:0;border-bottom:1px solid var(--cg-line)}.cuigengji .track-row-line.is-current{background:color-mix(in srgb,var(--cg-accent) 4%,transparent)}.cuigengji .track-chapter{position:absolute;left:0;width:var(--ruler-width);padding:8px 10px;border-right:1px solid var(--cg-line);background:var(--cg-paper);z-index:2;overflow:hidden}.cuigengji .track-chapter-title{display:flex;flex-direction:column;gap:4px;text-align:left;width:100%;border:0;padding:4px 0;background:transparent;white-space:normal}.cuigengji .track-chapter-title strong{font-size:13px;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.cuigengji .track-chapter-title small{font-size:10px;color:var(--cg-muted);line-height:1.4;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}.cuigengji .track-chapter-title[aria-current]{color:var(--cg-accent)}.cuigengji .track-chapter-actions{display:flex;gap:4px;margin:6px 0}.cuigengji .track-chapter-actions button{font-size:11px;padding:5px 6px;min-height:32px;border:0;color:var(--cg-accent);background:var(--cg-wash)}.cuigengji .track-plan{width:100%;display:flex;flex-direction:column;align-items:flex-start;text-align:left;height:64px;margin:6px 0;padding:6px 8px;border:0;border-left:3px solid var(--card-idea,#3b82f6);border-radius:4px;background:var(--cg-wash);gap:3px;white-space:normal}.cuigengji .track-plan.status-selected{border-left-color:var(--card-selected,#d97706)}.cuigengji .track-plan.status-written{border-left-color:var(--card-written,#16a34a)}.cuigengji .track-plan.status-dropped{border-left-color:var(--card-dropped,#a85c6a)}.cuigengji .track-plan strong{font-size:12px;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.cuigengji .track-plan small{font-size:10px;color:var(--cg-muted)}.cuigengji .track-bar{position:absolute;width:var(--lane-width);padding:12px 12px 12px 17px;display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;text-align:left;white-space:normal;border:1px solid color-mix(in srgb,var(--track-color) 35%,var(--cg-line));border-left:4px solid var(--track-color);border-radius:8px;background:color-mix(in srgb,var(--track-color) 8%,var(--cg-paper));color:var(--cg-ink);--track-color:var(--cg-accent)}.cuigengji .track-bar.kind-person{--track-color:var(--card-character,#8b5cf6)}.cuigengji .track-bar.kind-foreshadow{--track-color:var(--card-selected,#d97706)}.cuigengji .track-bar.is-current{outline:2px solid var(--track-color);outline-offset:1px;background:color-mix(in srgb,var(--track-color) 16%,var(--cg-paper))}.cuigengji .track-bar.is-planned{border-style:dashed;border-left-style:solid}.cuigengji .track-bar.is-abandoned{opacity:.6}.cuigengji .track-bar-label{position:sticky;top:52px;display:flex;flex-direction:column;gap:6px;max-height:100%;overflow:hidden}.cuigengji .track-bar-label strong{font-size:13px;line-height:1.6;overflow-wrap:anywhere}.cuigengji .track-bar-label small{font-size:10px;color:var(--cg-muted);line-height:1.5;overflow-wrap:anywhere}.cuigengji .track-mark{position:absolute;left:-6px;width:8px;height:8px;border:2px solid var(--track-color);background:var(--cg-paper);border-radius:50%;pointer-events:none}.cuigengji .track-end-label{position:absolute;bottom:8px;left:17px;font-size:10px;color:var(--track-color)}.cuigengji .track-help{font-size:11px;color:var(--cg-muted);line-height:1.7;margin:10px 0}.cuigengji .track-empty{padding:12px;font-size:12px;color:var(--cg-muted)}.cuigengji .story-position-slider{display:flex;align-items:center;gap:10px;font-size:11px;color:var(--cg-muted);margin-bottom:14px}.cuigengji .story-position-slider input{flex:1;min-width:0;padding:0;accent-color:var(--cg-accent)}.cuigengji .story-mobile-panel{display:none}.cuigengji .story-graph-create{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}.cuigengji .story-graph-create button{min-height:34px;font-size:11px}.cuigengji .stage-graph-menu{position:fixed;z-index:30;display:flex;flex-direction:column;padding:6px;background:var(--cg-paper);border:1px solid var(--cg-line);border-radius:8px;box-shadow:0 6px 24px #0002}.cuigengji .stage-graph-menu button{font-size:12px;border:0;min-height:36px;text-align:left;background:transparent}
@container(max-width:900px){.cuigengji .story-workspace{display:block}.cuigengji .story-inspector{display:none}.cuigengji .story-mobile-panel{display:block;margin:12px 0}.cuigengji .story-mobile-panel summary{font-size:12px;color:var(--cg-accent);padding:10px 0}.cuigengji button.story-mobile-graph{display:inline-flex;color:var(--cg-accent)}.cuigengji .story-context{grid-template-columns:1fr}.cuigengji .timeline-page{padding:12px}.cuigengji .timeline-tracks{--ruler-width:140px;--lane-width:146px}.cuigengji .track-chapter{padding-left:8px;padding-right:8px}.cuigengji .story-axis-tools{gap:6px;margin-bottom:14px;flex-wrap:wrap}.cuigengji .story-mode-switch button{padding:6px 10px}.cuigengji .track-scroll{max-height:62dvh}.cuigengji .story-graph-modal .story-graph{height:50dvh;min-height:260px;max-height:none}}
`;
